
local da=[==[]==]
local yamn=
(function(...)
local tf={51,76,93,67,9,139,48,147,193,184,130,82,51,38,174,189,30,98,0,133}
local ijvmw=bit32 or bit
local sls=ijvmw.bxor
for cctw=1,#tf do tf[cctw]=sls(tf[cctw],(40*cctw+216)%256) end
local upukv="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local jtm={}
for fcbxv=1,#upukv do jtm[upukv:byte(fcbxv)]=fcbxv-1 end
local function kia(str)
  local R={} local acc,nb=0,0
  for gbzoa=1,#str do
    local v=jtm[str:byte(gbzoa)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function fq(key,data)
  local S={} for ici=0,255 do S[ici]=ici end
  local j=0
  for aojhz=0,255 do
    j=(j+S[aojhz]+key[(aojhz%#key)+1])%256
    S[aojhz],S[j]=S[j],S[aojhz]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(sls(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=fq(tf,kia(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local ncvr=nf()
return function(big) return ncvr(big) end
end)(...)

return yamn(da)
